/// <summary>
///    The <c>METItemPackChangeCompletedBusinessEvent</c> class extends <c>BusinessEventsBase</c> to provide customer status change business event.
/// </summary>
[BusinessEvents(classStr(METItemPackChangeCompletedBusinessEventContract),
    "@MET:ItemPackChangeCompletedBusinessEventName",
    "@MET:ItemPackChangeCompletedBusinessEventDescHelptext",
    ModuleAxapta::Inventory)]
internal final class METItemPackChangeCompletedBusinessEvent extends BusinessEventsBase
{
    private METTempItemPackChg tempItemPackChg;
    private ItemId itemId;
    private List inventSiteId;

}

Method.Source:
/// <summary>
/// Constructs a new METItemPackChangeCompletedBusinessEvent business event.
/// </summary>
/// <param name = "_itemId">Item Id</param>
/// <param name = "_tempItemPackChg">List of Temp Item Pack Change</param>
/// <param name = "_inventSiteId">InventSiteId</param>
/// <returns>A new <c>METItemPackChangeCompletedBusinessEvent</c> business event.</returns>
public static METItemPackChangeCompletedBusinessEvent newFromItemPackChangeCompleted(ItemId _itemId, METTempItemPackChg _tempItemPackChg, list _inventSiteId)
{
    METItemPackChangeCompletedBusinessEvent event = new METItemPackChangeCompletedBusinessEvent();

    event.parmItemId(_itemId);
    event.parmInventSiteId(_inventSiteId);
    event.parmtempItemPackChg(_tempItemPackChg);

    return event;
}

/// <summary>
/// Get or set inventSite id
/// </summary>
/// <param name = "_inventSiteId">InventSiteId</param>
/// <returns>InventSiteId</returns>
private List parmInventSiteId(List _inventSiteId = inventSiteId)
{
    inventSiteId = _inventSiteId;

    return inventSiteId;
}

/// <summary>
/// Get or set Item id
/// </summary>
/// <param name = "_itemId">Item Id</param>
/// <returns>ItemId</returns>
private ItemId parmItemId(ItemId _itemId = itemId)
{
    itemId = _itemId;

    return itemId;
}

/// <summary>
/// List of TempItemPackChange list
/// </summary>
/// <param name = "_tempItemPackChg">TempItemPackChange list</param>
/// <returns>TempItemPackChange list</returns>
private METTempItemPackChg parmtempItemPackChg(METTempItemPackChg _tempItemPackChg = tempItemPackChg)
{
    tempItemPackChg = _tempItemPackChg;

    return tempItemPackChg;
}

/// <summary>
/// Overrides to provide customer status change data.
/// </summary>
/// <returns>The <c>METCustomerStatusChangeBusinessEventContract</c> of the event.</returns>
public BusinessEventsContract buildContract()
{
    return METItemPackChangeCompletedBusinessEventContract::newFromItemPackChangeCompleted(itemId, tempItemPackChg, inventSiteId);
}

/// <summary>
/// creates new object
/// </summary>
private void new()
{
}
